CREATE DATABASE IF NOT EXISTS savora CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE savora;

CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, phone VARCHAR(30), role VARCHAR(20) NOT NULL DEFAULT 'CUSTOMER', avatar VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_users_email(email));
CREATE TABLE categories (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE, icon VARCHAR(80) NOT NULL, image VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE restaurants (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, slug VARCHAR(170) NOT NULL UNIQUE, description TEXT, image VARCHAR(500), banner VARCHAR(500), cuisine VARCHAR(180), rating DECIMAL(2,1) DEFAULT 0, review_count INT DEFAULT 0, delivery_minutes INT DEFAULT 30, delivery_fee DECIMAL(10,2) DEFAULT 0, minimum_order DECIMAL(10,2) DEFAULT 0, active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_restaurants_active_rating(active,rating));
CREATE TABLE foods (id BIGINT PRIMARY KEY AUTO_INCREMENT, restaurant_id BIGINT NOT NULL, category_id BIGINT, name VARCHAR(150) NOT NULL, description TEXT, image VARCHAR(500), price DECIMAL(10,2) NOT NULL, rating DECIMAL(2,1) DEFAULT 0, vegetarian BOOLEAN DEFAULT FALSE, available BOOLEAN DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL, INDEX idx_foods_restaurant(restaurant_id), INDEX idx_foods_category(category_id));
CREATE TABLE addresses (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, label VARCHAR(60) NOT NULL, line1 VARCHAR(200) NOT NULL, line2 VARCHAR(200), city VARCHAR(80) NOT NULL, state VARCHAR(80) NOT NULL, postal_code VARCHAR(20) NOT NULL, is_default BOOLEAN DEFAULT FALSE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE wishlist_items (user_id BIGINT NOT NULL, food_id BIGINT NOT NULL, PRIMARY KEY(user_id,food_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(food_id) REFERENCES foods(id) ON DELETE CASCADE);
CREATE TABLE orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, restaurant_id BIGINT NOT NULL, address_id BIGINT, status VARCHAR(30) NOT NULL DEFAULT 'PLACED', subtotal DECIMAL(10,2) NOT NULL, tax DECIMAL(10,2) NOT NULL, delivery_fee DECIMAL(10,2) NOT NULL, discount DECIMAL(10,2) NOT NULL DEFAULT 0, total DECIMAL(10,2) NOT NULL, coupon VARCHAR(40), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(restaurant_id) REFERENCES restaurants(id), FOREIGN KEY(address_id) REFERENCES addresses(id), INDEX idx_orders_user_created(user_id,created_at));
CREATE TABLE order_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, food_id BIGINT NOT NULL, name VARCHAR(150) NOT NULL, price DECIMAL(10,2) NOT NULL, quantity INT NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(food_id) REFERENCES foods(id));
CREATE TABLE reviews (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, restaurant_id BIGINT, food_id BIGINT, rating INT NOT NULL, comment VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE, FOREIGN KEY(food_id) REFERENCES foods(id) ON DELETE CASCADE);
